def find_kth_neq_number(K):
    def is_neq_number(n):
        s = str(n)
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                return False
        return True

    count = 0
    num = 1
    while True:
        if is_neq_number(num):
            count += 1
            if count == K:
                return num
        num += 1
